                                &lt;option value=&quot;2&quot; {% if user.role_id == 2 %}selected{% endif %}&gt;Docent&lt;/option&gt;
                                &lt;option value=&quot;3&quot; {% if user.role_id == 3 %}selected{% endif %}&gt;Admin&lt;/option&gt;
                            &lt;/select&gt;
                            &lt;button type=&quot;submit&quot; class=&quot;btn-update&quot;&gt;Update&lt;/button&gt;
