                    &lt;input type=&quot;hidden&quot; name=&quot;user_id&quot; value=&quot;{{ row.id }}&quot;&gt;
                    &lt;button type=&quot;submit&quot; class=&quot;btn-delete&quot;&gt;Delete&lt;/button&gt;
                    &lt;/form&gt;
                &lt;/td&gt;
            &lt;/tr&gt;
    {% endfor %}
    &lt;/tbody&gt;
&lt;/table&gt;&quot;&quot;&quot;


@app.route(&quot;/ajaxlivesearch&quot;, methods=[&quot;POST&quot;, &quot;GET&quot;])
def ajaxlivesearch():
    conn = get_db_connection()
    user = &quot;&quot;  # default value for `GET`
    numrows = 0  # default value for `GET`

    if request.method == &quot;POST&quot;:
        search_word = request.form.get(&quot;query&quot;, &quot;&quot;)
        print(f&quot;{search_word=}&quot;)
        if search_word == &quot;&quot;:
            query = &quot;SELECT * from users ORDER BY id&quot;
            conn.execute(query)
        else:
            query = &quot;SELECT * from users WHERE name LIKE ? OR email LIKE ? ORDER BY id DESC LIMIT 20&quot;
            conn.execute(query, (f&quot;%{search_word}%&quot;, f&quot;%{search_word}%&quot;))
        user = conn.fetchall()
        numrows = conn.rowcount
        numrows = len(user)

    print(f&quot;{numrows=}&quot;)
    print(user)

    # return jsonify({&quot;htmlresponse&quot;: render_template(&quot;response.html&quot;, user=user, numrows=numrows)})

    return jsonify(
        {
            &quot;htmlresponse&quot;: render_template_string(
                response_html, user=user, numrows=numrows
            )
        }
    )


